{
  "name": "PVLogger日志文件夹管理器",
  "name_en": "PVLogger Log Folder Manager",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于读取、整理和解析PVLogger生成的日志文件夹。它可加载主配置与文件清单、读取各PV日志文本、并行解析未处理日志、识别新增日志文件，以及提取电机相关PV事件，常用于实验过程数据回顾、运行状态追踪和故障排查。",
  "description_en": "This is a non-physical software component for reading, organizing, and parsing PVLogger log folders. It loads the main configuration and file list, reads PV log text, parses unprocessed logs in parallel, detects newly added log files, and extracts motor-related PV events. It is used for experiment data review, run-state tracking, and troubleshooting.",
  "actions": [
    {
      "action_name": "auto-read_folder",
      "description": "读取PVLogger日志文件夹，加载配置、日志文件列表及起止时间等信息。",
      "description_en": "Read the PVLogger log folder and load configuration, log file list, and start/stop time information."
    },
    {
      "action_name": "auto-read_all_logs_text",
      "description": "读取全部PV日志文件的文本内容。",
      "description_en": "Read the text contents of all PV log files."
    },
    {
      "action_name": "auto-parse_logfiles",
      "description": "并行解析尚未处理的PV日志文件数据。",
      "description_en": "Parse unprocessed PV log files in parallel."
    },
    {
      "action_name": "auto-reset_new_logfiles",
      "description": "重置并标记新发现的日志文件，可选择同时解析其数据。",
      "description_en": "Reset and mark newly discovered log files, with optional data parsing."
    },
    {
      "action_name": "auto-read_logfile",
      "description": "按PV名称读取单个日志文件并记录文件时间戳。",
      "description_en": "Read a single log file by PV name and record its file timestamp."
    },
    {
      "action_name": "auto-read_motor_events",
      "description": "读取并整理电机相关PV的事件数据。",
      "description_en": "Read and organize event data for motor-related PVs."
    },
    {
      "action_name": "auto-start_next_process",
      "description": "启动下一个日志解析子进程。",
      "description_en": "Start the next log-parsing subprocess."
    }
  ],
  "tag_hints": [
    "PVLogger",
    "EPICS PV logs",
    "log folder parsing",
    "experiment data review",
    "multiprocessing log parsing",
    "motor event extraction",
    "archived control system data"
  ]
}

